// Helper function to count integers in the input sequence
method CountInt(values: seq<object>) returns (count: int)
    requires values != null
    ensures count >= 0
    ensures count == |{ v | v in values | v is int }|
{
    count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= i <= |values|
        invariant count == |{ v | j | j in values[0..i] | v is int }|
    {
        if values[i] is int {
            count := count + 1;
        }
        i := i + 1;
    }
}
